// F02: the promotion PR body is rendered from the data it is given, and says nothing more.
import { describe, expect, test } from "bun:test";
import { renderPrBody, type PrBodyInput } from "../src/act/pr-body.ts";

const base: PrBodyInput = {
  repo: "rajkaria/roster",
  incumbent: "B",
  promoted: "E",
  tasks: [
    {
      id: "F01",
      incumbentPass: true,
      candidatePass: true,
      costUsd: 0.4,
      traceUrl: "https://neatlogs.example/t/F01",
      entireUrl: "https://entire.io/c/F01",
    },
    { id: "F02", incumbentPass: true, candidatePass: true, costUsd: 0.75 },
    { id: "F03", incumbentPass: true, candidatePass: false, costUsd: null, traceUrl: "https://neatlogs.example/t/F03" },
    { id: "F04", incumbentPass: false, candidatePass: true, costUsd: 2 },
  ],
  rejected: [{ candidate: "F", reasons: ["regression on F03", "scope violation on F04"] }],
  evidenceLevel: "B",
};

/** The body split into sections keyed by their "## " heading. */
function sections(md: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const block of md.split(/\n(?=## )/)) {
    const heading = /^## (.+)$/m.exec(block)?.[1];
    if (heading) out[heading] = block.slice(block.indexOf("\n") + 1).replace(/\n+$/, "");
  }
  return out;
}

describe("renderPrBody", () => {
  test("emits the four sections in order", () => {
    const md = renderPrBody(base);
    expect(Object.keys(sections(md))).toEqual(["Summary", "Evidence", "Rejected candidates", "Links"]);
  });

  test("evidence table has one row per task, one column per side, pass as ✓/✗", () => {
    const md = renderPrBody(base);
    const rows = md.split("\n").filter((l) => /^\| `/.test(l));
    expect(rows).toEqual([
      "| `F01` | ✓ | ✓ | 0.40 |",
      "| `F02` | ✓ | ✓ | 0.75 |",
      "| `F03` | ✓ | ✗ | n/a |",
      "| `F04` | ✗ | ✓ | 2.00 |",
    ]);
  });

  test("totals line counts both sides over the same n", () => {
    const md = renderPrBody(base);
    expect(sections(md).Summary).toContain("3 of 4 tasks passed (incumbent 3 of 4)");
  });

  test("prints the evidence level with its source", () => {
    expect(sections(renderPrBody(base)).Summary).toContain("- Evidence level: B (controlled replay)");
    expect(sections(renderPrBody({ ...base, evidenceLevel: "C" })).Summary).toContain(
      "- Evidence level: C (pre-registered forward run)",
    );
  });

  test("lists each rejected candidate with its reasons", () => {
    const md = renderPrBody({
      ...base,
      rejected: [
        { candidate: "F", reasons: ["regression on F03", "scope violation on F04"] },
        { candidate: "D", reasons: ["cost 0.90 over budget 0.50"] },
      ],
    });
    const rejected = sections(md)["Rejected candidates"]!;
    expect(rejected).toContain("### `F`");
    expect(rejected).toContain("- regression on F03");
    expect(rejected).toContain("- scope violation on F04");
    expect(rejected).toContain("### `D`");
    expect(rejected).toContain("- cost 0.90 over budget 0.50");
  });

  test("an empty rejected list says None and names no candidate", () => {
    const md = renderPrBody({ ...base, rejected: [] });
    expect(sections(md)["Rejected candidates"]).toBe("None");
  });

  test("links the tasks that carry urls, and only those", () => {
    const links = sections(renderPrBody(base)).Links!;
    expect(links).toContain("- `F01`: [trace](https://neatlogs.example/t/F01), [entire](https://entire.io/c/F01)");
    expect(links).toContain("- `F03`: [trace](https://neatlogs.example/t/F03)");
    expect(links).not.toContain("F02");
    expect(links).not.toContain("F04");
  });

  test("no urls anywhere says None", () => {
    const md = renderPrBody({ ...base, tasks: base.tasks.map(({ traceUrl: _t, entireUrl: _e, ...rest }) => rest) });
    expect(sections(md).Links).toBe("None");
  });

  test("zero tasks still renders every section", () => {
    const md = renderPrBody({ ...base, tasks: [], rejected: [] });
    expect(sections(md).Summary).toContain("0 of 0 tasks passed (incumbent 0 of 0)");
    expect(sections(md)["Rejected candidates"]).toBe("None");
    expect(sections(md).Links).toBe("None");
    expect(md.split("\n").filter((l) => /^\| `/.test(l))).toEqual([]);
  });

  test("prints no adjective and no number the input does not support", () => {
    const md = renderPrBody(base);
    expect(md).not.toMatch(/significant|best|better|improved|faster|worse|cheaper/i);
    // No rate or share is invented: 3 of 4 passed, and no percentage is printed.
    expect(md).not.toContain("%");
    expect(md).not.toContain("75");
    for (const n of md.match(/\d+(?:\.\d+)?/g) ?? []) {
      expect(["0.40", "0.75", "2.00", "3", "4", "01", ...Object.keys(sections(md))]).toContain(n);
    }
  });
});

